 (function () {
    function initBadge() {
        const salariedLabel = document.querySelector('label[for="occupation_salaried"]');
        const salariedInput = document.querySelector('#occupation_salaried');
        if (!salariedLabel || !salariedInput) return;
        salariedLabel.style.position = "relative";
        let badge = salariedLabel.querySelector(".salaried-tag");
        if (!badge) {
            badge = document.createElement("div");
            badge.className = "salaried-tag";
            badge.innerHTML = "15% Discount";
            Object.assign(badge.style, {
                position: "absolute",
                color: "var(--color-text-success)",
                borderRadius: "4px",
                padding: "0.25rem 0.5rem",
                fontSize: "11px",
                lineHeight: "15px",
                fontWeight: "400",
                top: "68%",
                left: "50%",
                transform: "translateX(-50%)",
                width: "max-content",
                background: "var(--color-background-highlight)",
                zIndex: "10",
                display: salariedInput.checked ? "block" : "none"
            });
            salariedLabel.appendChild(badge);
        } else {
            badge.style.display = salariedInput.checked ? "block" : "none";
        }
    }
    // Check every 300ms in case the popup content is recreated
    setInterval(initBadge, 300);
})(); 
