						try{/* =============================================================================
 * Axis Max Life — Investment Calculator quote page (?stage=quote)
 *
 * Pre-selects the "8% — As per IRDAI Mandate" return in the past-returns
 * dropdown instead of the product's default high-growth fund.
 *
 * All four products render the same dropdown component
 * (`.custom-select.rateOfInterest`), so one script covers:
 *   • Wealth              (marketLinkWealthPlan / capitalGuaranteeSolution)
 *   • Child               (marketLinkChildPlan)
 *   • Retirement/Pension  (foreverYoungPension)
 *   • GIFT City           (smartInternationalPlan, USD)
 *
 * Re-applies on SPA product switches ("Change Plan", plan-type and
 * cover-multiple toggles) and stands down as soon as the visitor picks a
 * fund themselves. Products without a returns dropdown (e.g. guaranteedSaving)
 * are simply ignored.
 * ========================================================================== */
(function () {
  'use strict';
  var NS = '__amlRoiIrdaiPreselect';
  if (window[NS]) { window[NS].kick(); return; }   // VWO re-runs variation JS on route change
  /* ------------------------------ config --------------------------------- */
  var CFG = {
    target:            8,      // 8 or 4 — the IRDAI mandated rate to preselect
    hideUntilApplied:  true,   // hide the returns selector until it reads 8%
    revealAfterMs:     6000,   // failsafe: stop hiding after this, applied or not
    respectUserChoice: true,   // stand down once the visitor picks a fund
    maxAttempts:       8,      // per product, guards against fighting the app
    heartbeatMs:       500
  };
  /* ----------------------------- selectors ------------------------------- */
  var BOX  = '.custom-select.rateOfInterest';
  var BTN  = 'button.rateOfInterest-select';
  var LIST = '#rateOfInterest-select';
  var OPT  = 'a.custom-select-option';
  var applied    = {};   // context key -> true, purely informational
  var overridden = {};   // context key -> true, visitor picked a fund here
  var attempts   = {};   // context key -> tries spent
  var ours       = false;
  var startedAt  = Date.now();
  /* -------- styling: silence our programmatic open, optional pre-hide ----- */
  var style = document.createElement('style');
  style.setAttribute('data-amlroi', '');
  style.textContent =
    BOX + '.amlroi-busy ' + LIST + '{visibility:hidden!important;opacity:0!important;pointer-events:none!important;}' +
    BOX + '.amlroi-pending{visibility:hidden!important;}';
  (document.head || document.documentElement).appendChild(style);
  /* ------------------------------ helpers -------------------------------- */
  // Identifies the product currently on screen, so each one gets its own
  // attempt budget and its own "the visitor overrode us" flag.
  function contextKey() {
    try {
      var q = JSON.parse(sessionStorage.getItem('quote') || '{}');
      var plan = q.activeSavingPlan || {};
      return [q.planSelectorTab, q.savingProductGroup, plan.productCode, q.currency].join('|');
    } catch (e) { return 'default'; }
  }
  function currentRate(box) {
    var btn = box.querySelector(BTN) || box.querySelector('button');
    if (!btn) return null;
    var m = (btn.textContent || '').trim().match(/^(\d+(?:\.\d+)?)\s*%/);
    return m ? parseFloat(m[1]) : null;
  }
  // The IRDAI rows read "8%  Return at 8%  As per IRDAI Mandate".
  // Match the rate first, prefer the row that also says IRDAI.
  function findTargetOption(box) {
    var opts  = box.querySelectorAll(LIST + ' ' + OPT);
    var rate  = new RegExp('^' + CFG.target + '(\\.0+)?\\s*%');
    var loose = null;
    for (var i = 0; i < opts.length; i++) {
      var txt = (opts[i].textContent || '').replace(/\s+/g, ' ').trim();
      if (!rate.test(txt)) continue;
      if (/IRDAI/i.test(txt)) return opts[i];
      loose = loose || opts[i];
    }
    return loose;
  }
  function isOpen(box) {
    var btn = box.querySelector(BTN) || box.querySelector('button');
    return !!(btn && btn.className.indexOf('active') !== -1);
  }
  function reveal(box)  { box.classList.remove('amlroi-pending'); }
  function preHide(box) {
    if (CFG.hideUntilApplied && Date.now() - startedAt < CFG.revealAfterMs) box.classList.add('amlroi-pending');
    else reveal(box);
  }
  function finish(box, key, ok) {
    ours = false;
    box.classList.remove('amlroi-busy');
    if (ok) applied[key] = true;
    reveal(box);
  }
  /* ------------------------------- core ---------------------------------- */
  function apply() {
    var box = document.querySelector(BOX);
    if (!box) return;                                  // product has no returns dropdown
    var key = contextKey();
    if (overridden[key])                  { reveal(box); return; }
    // Deliberately does NOT latch a "done" flag here: during a product switch
    // the new context key lands before the dropdown re-renders, so a single
    // reading of 8% is not proof the new product is on 8%. The heartbeat
    // re-checks and the attempt budget below stops any runaway.
    if (currentRate(box) === CFG.target)  { reveal(box); return; }
    if ((attempts[key] || 0) >= CFG.maxAttempts) { reveal(box); return; }
    if (ours)      return;                             // a pass is already running
    if (isOpen(box)) { preHide(box); return; }         // visitor has it open — don't fight
    var btn = box.querySelector(BTN) || box.querySelector('button');
    if (!btn) return;
    attempts[key] = (attempts[key] || 0) + 1;
    preHide(box);
    ours = true;
    box.classList.add('amlroi-busy');
    if (!box.querySelector(LIST + ' ' + OPT)) btn.click();   // open so React renders the options
    var tries = 0;
    (function pick() {
      var opt = findTargetOption(box);
      if (opt) {
        opt.click();
        setTimeout(function () { finish(box, key, currentRate(box) === CFG.target); }, 150);
        return;
      }
      if (++tries > 40) {                              // ~1s — bail and put the UI back
        if (isOpen(box)) btn.click();
        finish(box, key, false);
        return;
      }
      setTimeout(pick, 25);
    })();
  }
  /* ---------------------- back off on a manual choice --------------------- */
  if (CFG.respectUserChoice) {
    document.addEventListener('click', function (e) {
      if (ours) return;
      var node = e.target && e.target.nodeType === 1 ? e.target : e.target && e.target.parentElement;
      if (!node || !node.closest) return;
      if (node.closest(OPT) && node.closest(BOX)) overridden[contextKey()] = true;
    }, true);
  }
  /* -------------------- keep up with SPA re-renders ----------------------- */
  var pending = null;
  function kick() {
    if (pending) return;
    pending = setTimeout(function () { pending = null; try { apply(); } catch (e) {} }, 80);
  }
  new MutationObserver(kick).observe(document.documentElement, { childList: true, subtree: true });
  setInterval(kick, CFG.heartbeatMs);
  kick();
  window[NS] = { kick: kick, apply: apply, cfg: CFG, applied: applied, overridden: overridden, attempts: attempts };
})();
}catch(e) {VWO._.vAEH(e);}
